-- ORBIT initial schema
create extension if not exists "pgcrypto";
create table public.profiles(id uuid primary key references auth.users(id) on delete cascade, full_name text, email text, avatar_url text, preferred_language text default 'en' check (preferred_language in ('en','id')), created_at timestamptz default now());
create table public.conversations(id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, title text not null default 'New conversation', created_at timestamptz default now(), updated_at timestamptz default now());
create table public.messages(id uuid primary key default gen_random_uuid(), conversation_id uuid not null references public.conversations(id) on delete cascade, role text not null check (role in ('user','assistant','system')), content text not null, created_at timestamptz default now());
create table public.tasks(id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, title text not null, description text default '', priority text not null default 'Medium' check (priority in ('Low','Medium','High','Urgent')), status text not null default 'todo' check (status in ('todo','in-progress','completed')), due_date date, estimated_duration int default 30 check (estimated_duration >= 0), category text default 'General', created_at timestamptz default now(), updated_at timestamptz default now());
create table public.subtasks(id uuid primary key default gen_random_uuid(), task_id uuid not null references public.tasks(id) on delete cascade, title text not null, is_completed boolean default false, created_at timestamptz default now());
create table public.memories(id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, content text not null, category text default 'Preference', created_at timestamptz default now(), updated_at timestamptz default now());
create table public.schedules(id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, task_id uuid references public.tasks(id) on delete set null, title text not null, start_time timestamptz not null, end_time timestamptz not null, created_at timestamptz default now(), check (end_time > start_time));
create index idx_conversations_user on public.conversations(user_id); create index idx_messages_conv on public.messages(conversation_id, created_at); create index idx_tasks_user_due on public.tasks(user_id, due_date); create index idx_subtasks_task on public.subtasks(task_id); create index idx_memories_user on public.memories(user_id); create index idx_schedules_user_start on public.schedules(user_id, start_time);
alter table public.profiles enable row level security; alter table public.conversations enable row level security; alter table public.messages enable row level security; alter table public.tasks enable row level security; alter table public.subtasks enable row level security; alter table public.memories enable row level security; alter table public.schedules enable row level security;
create policy "own profile" on public.profiles for all using (auth.uid()=id) with check (auth.uid()=id);
create policy "own conversations" on public.conversations for all using (auth.uid()=user_id) with check (auth.uid()=user_id);
create policy "own messages" on public.messages for all using (exists(select 1 from public.conversations c where c.id=conversation_id and c.user_id=auth.uid())) with check (exists(select 1 from public.conversations c where c.id=conversation_id and c.user_id=auth.uid()));
create policy "own tasks" on public.tasks for all using (auth.uid()=user_id) with check (auth.uid()=user_id);
create policy "own subtasks" on public.subtasks for all using (exists(select 1 from public.tasks t where t.id=task_id and t.user_id=auth.uid())) with check (exists(select 1 from public.tasks t where t.id=task_id and t.user_id=auth.uid()));
create policy "own memories" on public.memories for all using (auth.uid()=user_id) with check (auth.uid()=user_id);
create policy "own schedules" on public.schedules for all using (auth.uid()=user_id) with check (auth.uid()=user_id);
